import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { getTests, getCategories } from '../../utils/api';
import {
  Search, Upload, X, Plus, Minus, FileText,
  Download, FlaskConical, Clock, Printer,
  CheckCircle, AlertCircle, ChevronDown, ChevronUp,
  ShoppingCart,
} from 'lucide-react';
import './EstimatePage.css';

const LAB_NAME    = 'LabCollect Diagnostics';
const LAB_ADDRESS = 'Ludhiana, Punjab, India';
const LAB_PHONE   = '+91 98765 43210';

/* ── debounce hook ────────────────────────────────────────── */
function useDebounce(value, delay) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
}

/* ── Single test row in estimate list ─────────────────────── */
function EstimateRow({ test, onRemove }) {
  return (
    <div className="est-row">
      <div className="est-row-info">
        <div className="est-row-name">{test.name}</div>
        <div className="est-row-meta">
          <span className="est-code">{test.code}</span>
          {test.sample_type && <span>· {test.sample_type}</span>}
          {test.report_time && <span>· {test.report_time}</span>}
          {test.fasting_required ? (
            <span className="est-fasting">Fasting required</span>
          ) : null}
        </div>
      </div>
      <div className="est-row-price">₹{parseFloat(test.base_price).toFixed(0)}</div>
      <button className="est-remove" onClick={() => onRemove(test.id)} title="Remove">
        <X size={13}/>
      </button>
    </div>
  );
}

/* ── Prescription upload zone ─────────────────────────────── */
function PrescriptionUpload({ file, onChange }) {
  const inputRef  = useRef();
  const [preview, setPreview] = useState(null);
  const [dragOver, setDragOver] = useState(false);

  const handleFile = (f) => {
    if (!f) return;
    const allowed = ['image/jpeg','image/png','image/webp','application/pdf'];
    if (!allowed.includes(f.type)) {
      alert('Please upload a JPG, PNG, WEBP, or PDF file');
      return;
    }
    if (f.size > 5 * 1024 * 1024) {
      alert('File must be under 5 MB');
      return;
    }
    onChange(f);
    if (f.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = e => setPreview(e.target.result);
      reader.readAsDataURL(f);
    } else {
      setPreview(null);
    }
  };

  const clear = (e) => {
    e.stopPropagation();
    onChange(null);
    setPreview(null);
    if (inputRef.current) inputRef.current.value = '';
  };

  return (
    <div
      className={`prescription-zone ${dragOver ? 'drag-over' : ''} ${file ? 'has-file' : ''}`}
      onClick={() => !file && inputRef.current.click()}
      onDragOver={e => { e.preventDefault(); setDragOver(true); }}
      onDragLeave={() => setDragOver(false)}
      onDrop={e => { e.preventDefault(); setDragOver(false); handleFile(e.dataTransfer.files[0]); }}
    >
      <input
        ref={inputRef}
        type="file"
        accept=".jpg,.jpeg,.png,.webp,.pdf"
        hidden
        onChange={e => handleFile(e.target.files[0])}
      />
      {file ? (
        <div className="pz-file">
          {preview ? (
            <img src={preview} alt="prescription" className="pz-preview"/>
          ) : (
            <div className="pz-pdf-icon"><FileText size={36} color="var(--primary)"/></div>
          )}
          <div className="pz-file-info">
            <div className="pz-filename">{file.name}</div>
            <div className="pz-filesize">{(file.size / 1024).toFixed(0)} KB</div>
          </div>
          <button className="pz-clear" onClick={clear}><X size={14}/></button>
        </div>
      ) : (
        <div className="pz-empty">
          <div className="pz-upload-icon"><Upload size={28}/></div>
          <div className="pz-label">Upload Prescription</div>
          <div className="pz-hint">Drag & drop or click · JPG, PNG, PDF · Max 5 MB</div>
        </div>
      )}
    </div>
  );
}

/* ── Print-ready estimate ─────────────────────────────────── */
function printEstimate(selected, prescriptionNote, total) {
  const now    = new Date();
  const dateStr = now.toLocaleDateString('en-IN', { day:'numeric', month:'long', year:'numeric' });
  const timeStr = now.toLocaleTimeString('en-IN', { hour:'2-digit', minute:'2-digit' });

  const rows = selected.map((t, i) => `
    <tr>
      <td style="padding:10px 12px;border-bottom:1px solid #eee;">${i+1}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #eee;">
        <strong>${t.name}</strong><br/>
        <small style="color:#666;">${t.code}${t.sample_type ? ' · ' + t.sample_type : ''}</small>
      </td>
      <td style="padding:10px 12px;border-bottom:1px solid #eee;color:#666;">
        ${t.report_time || '—'}
      </td>
      <td style="padding:10px 12px;border-bottom:1px solid #eee;text-align:right;font-weight:600;">
        ₹${parseFloat(t.base_price).toFixed(0)}
      </td>
    </tr>`).join('');

  const html = `<!DOCTYPE html>
<html><head>
<meta charset="utf-8"/>
<title>Test Estimate — ${LAB_NAME}</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Segoe UI', Arial, sans-serif; padding: 40px; color: #1a2b3c; font-size: 13px; }
  .header { display: flex; justify-content: space-between; align-items: flex-start; padding-bottom: 20px; border-bottom: 3px solid #0A3D62; margin-bottom: 24px; }
  .lab-name { font-size: 22px; font-weight: 700; color: #0A3D62; }
  .lab-sub  { color: #5D7B96; margin-top: 4px; }
  .est-label { font-size: 12px; color: #5D7B96; }
  .est-num   { font-size: 20px; font-weight: 700; color: #00B4D8; font-family: monospace; }
  table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
  thead tr { background: #0A3D62; color: white; }
  thead th { padding: 10px 12px; text-align: left; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; }
  thead th:last-child { text-align: right; }
  .total-row td { padding: 14px 12px; border-top: 2px solid #0A3D62; font-weight: 700; font-size: 16px; }
  .total-row td:last-child { text-align: right; color: #0A3D62; font-size: 18px; }
  .note { background: #F0F4F8; border-left: 3px solid #00B4D8; padding: 12px 16px; border-radius: 0 6px 6px 0; margin-bottom: 20px; }
  .footer { text-align: center; margin-top: 40px; font-size: 11px; color: #999; }
  @media print { body { padding: 20px; } }
</style>
</head><body>
  <div class="header">
    <div>
      <div class="lab-name">${LAB_NAME}</div>
      <div class="lab-sub">${LAB_ADDRESS} · ${LAB_PHONE}</div>
    </div>
    <div style="text-align:right;">
      <div class="est-label">ESTIMATE</div>
      <div class="est-num">#EST-${now.getTime().toString().slice(-6)}</div>
      <div style="color:#666;margin-top:4px;">${dateStr} ${timeStr}</div>
    </div>
  </div>

  ${prescriptionNote ? `<div class="note"><strong>Prescription Note:</strong> ${prescriptionNote}</div>` : ''}

  <table>
    <thead>
      <tr>
        <th style="width:40px;">#</th>
        <th>Test / Service</th>
        <th>Report Time</th>
        <th style="text-align:right;">Price</th>
      </tr>
    </thead>
    <tbody>
      ${rows}
      <tr class="total-row">
        <td colspan="3">Total Estimate (${selected.length} test${selected.length !== 1 ? 's' : ''})</td>
        <td>₹${total.toFixed(0)}</td>
      </tr>
    </tbody>
  </table>

  <div class="note">
    This is an indicative estimate only. Final amount may vary based on collection type, applicable discounts, or additional tests.
    Prices are inclusive of sample collection at our centre.
  </div>

  <div class="footer">
    Valid for 7 days from date of issue · ${LAB_NAME} · ${LAB_PHONE}
  </div>

  <script>window.onload = function(){ window.print(); }</script>
</body></html>`;

  const win = window.open('', '_blank');
  win.document.write(html);
  win.document.close();
}

/* ══════════════════════════════════════════════════════════
   MAIN COMPONENT
══════════════════════════════════════════════════════════ */
export default function EstimatePage() {
  const [categories,  setCategories]  = useState([]);
  const [allTests,    setAllTests]    = useState([]);
  const [searchResults, setSearchResults] = useState([]);
  const [selected,    setSelected]    = useState([]);       // tests added to estimate
  const [query,       setQuery]       = useState('');
  const [searching,   setSearching]   = useState(false);
  const [prescription, setPrescription] = useState(null);   // File object
  const [prescNote,   setPrescNote]   = useState('');       // manual note from prescription
  const [activeCat,   setActiveCat]   = useState('');
  const [showSearch,  setShowSearch]  = useState(false);
  const [expandCats,  setExpandCats]  = useState({});

  const debouncedQuery = useDebounce(query, 280);

  // Initial data load
  useEffect(() => {
    Promise.all([getCategories(), getTests({ limit: 200, type: 'test' })]).then(([cats, tests]) => {
      setCategories(cats.data.categories || []);
      setAllTests(tests.data.tests || []);
    });
  }, []);

  // Search on debounced query
  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setSearchResults([]);
      setSearching(false);
      return;
    }
    setSearching(true);
    getTests({ search: debouncedQuery, limit: 30 })
      .then(r => setSearchResults(r.data.tests || []))
      .finally(() => setSearching(false));
  }, [debouncedQuery]);

  const addTest = (t) => {
    if (!selected.find(s => s.id === t.id)) {
      setSelected(prev => [...prev, t]);
    }
    setQuery('');
    setSearchResults([]);
  };

  const removeTest = (id) => setSelected(prev => prev.filter(t => t.id !== id));

  const total    = selected.reduce((s, t) => s + parseFloat(t.base_price || 0), 0);
  const fasting  = selected.some(t => t.fasting_required);

  // Tests by category for the browse panel
  const grouped = categories
    .map(cat => ({
      ...cat,
      tests: allTests.filter(t => t.category_id === cat.id && !selected.find(s => s.id === t.id)),
    }))
    .filter(cat => !activeCat || String(cat.id) === activeCat);

  const toggleCat = (id) =>
    setExpandCats(prev => ({ ...prev, [id]: !prev[id] }));

  return (
    <div className="estimate-page">
      {/* ── Hero ────────────────────────────────────────── */}
      <div className="est-hero">
        <div className="est-hero-inner">
          <div className="est-hero-badge">Cost Estimator</div>
          <h1 className="est-hero-title">
            Know your test costs<br/>
            <span className="est-hero-accent">before you book</span>
          </h1>
          <p className="est-hero-sub">
            Search tests prescribed by your doctor, upload your prescription,
            and get an instant estimate — no login required.
          </p>
        </div>
      </div>

      <div className="est-layout">
        {/* ══ LEFT — search + browse ══════════════════════ */}
        <div className="est-left">

          {/* Prescription upload */}
          <div className="est-card">
            <div className="est-card-title">
              <FileText size={16}/>
              Upload Prescription <span className="est-optional">(optional)</span>
            </div>
            <PrescriptionUpload file={prescription} onChange={setPrescription}/>
            {prescription && (
              <div className="form-group" style={{ marginTop: 10 }}>
                <label className="form-label">Add a note about your prescription</label>
                <textarea
                  className="form-control"
                  rows={2}
                  placeholder="e.g. Dr. Sharma prescribed CBC, TSH, and Vitamin D"
                  value={prescNote}
                  onChange={e => setPrescNote(e.target.value)}
                />
              </div>
            )}
          </div>

          {/* Search */}
          <div className="est-card">
            <div className="est-card-title"><Search size={16}/> Search Tests</div>
            <div className="est-search-wrap">
              <div className="est-search-bar">
                <Search size={15}/>
                <input
                  className="form-control"
                  placeholder="Type test name or code e.g. CBC, Thyroid, HbA1c…"
                  value={query}
                  onChange={e => { setQuery(e.target.value); setShowSearch(true); }}
                  onFocus={() => setShowSearch(true)}
                />
                {query && <button className="est-clear-q" onClick={() => setQuery('')}><X size={13}/></button>}
              </div>

              {/* Search results dropdown */}
              {showSearch && (query || searching) && (
                <div className="est-search-results">
                  {searching && <div className="est-search-loader">Searching…</div>}
                  {!searching && searchResults.length === 0 && query && (
                    <div className="est-search-empty">No tests found for "{query}"</div>
                  )}
                  {searchResults.map(t => {
                    const already = !!selected.find(s => s.id === t.id);
                    return (
                      <button
                        key={t.id}
                        className={`est-search-item ${already ? 'already' : ''}`}
                        onClick={() => !already && addTest(t)}
                        disabled={already}
                      >
                        <div className="esi-info">
                          <div className="esi-name">{t.name}</div>
                          <div className="esi-meta">
                            {t.code} · {t.category_name || '—'}
                            {t.sample_type && ` · ${t.sample_type}`}
                          </div>
                        </div>
                        <div className="esi-right">
                          <span className="esi-price">₹{parseFloat(t.base_price).toFixed(0)}</span>
                          {already
                            ? <span className="esi-added"><CheckCircle size={13}/> Added</span>
                            : <span className="esi-add"><Plus size={13}/> Add</span>
                          }
                        </div>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          </div>

          {/* Browse by category */}
          <div className="est-card">
            <div className="est-card-title" style={{ display:'flex', alignItems:'center', justifyContent:'space-between' }}>
              <span><FlaskConical size={16}/> Browse by Category</span>
              <select
                className="form-control"
                style={{ width:'auto', fontSize:12, padding:'4px 8px', height:'auto' }}
                value={activeCat}
                onChange={e => setActiveCat(e.target.value)}
              >
                <option value="">All Categories</option>
                {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
            </div>

            {grouped.map(cat => (
              cat.tests.length === 0 ? null : (
                <div key={cat.id} className="est-cat-group">
                  <button
                    className="est-cat-header"
                    onClick={() => toggleCat(cat.id)}
                  >
                    <span>{cat.name}</span>
                    <span style={{ display:'flex', alignItems:'center', gap:8 }}>
                      <span className="est-cat-count">{cat.tests.length}</span>
                      {expandCats[cat.id] ? <ChevronUp size={14}/> : <ChevronDown size={14}/>}
                    </span>
                  </button>

                  {expandCats[cat.id] && (
                    <div className="est-cat-tests">
                      {cat.tests.map(t => (
                        <button key={t.id} className="est-browse-item" onClick={() => addTest(t)}>
                          <div className="ebi-info">
                            <div className="ebi-name">{t.name}</div>
                            <div className="ebi-meta">
                              {t.code}
                              {t.sample_type && ` · ${t.sample_type}`}
                              {t.fasting_required && <span className="ebi-fasting"> · Fasting</span>}
                            </div>
                          </div>
                          <div className="ebi-right">
                            <span className="ebi-price">₹{parseFloat(t.base_price).toFixed(0)}</span>
                            <span className="ebi-add-icon"><Plus size={12}/></span>
                          </div>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              )
            ))}
          </div>
        </div>

        {/* ══ RIGHT — estimate summary ═════════════════════ */}
        <div className="est-right">
          <div className="est-summary-card">
            <div className="est-summary-header">
              <div className="est-summary-title">Your Estimate</div>
              {selected.length > 0 && (
                <button className="est-clear-all" onClick={() => setSelected([])}>Clear all</button>
              )}
            </div>

            {selected.length === 0 ? (
              <div className="est-empty-state">
                <div className="est-empty-icon"><ShoppingCart size={32}/></div>
                <div className="est-empty-text">Add tests to see your estimate</div>
                <div className="est-empty-hint">Search above or browse by category</div>
              </div>
            ) : (
              <>
                <div className="est-items">
                  {selected.map(t => (
                    <EstimateRow key={t.id} test={t} onRemove={removeTest}/>
                  ))}
                </div>

                {/* Alerts */}
                {fasting && (
                  <div className="est-alert fasting">
                    <AlertCircle size={14}/>
                    One or more tests require fasting for 8–10 hours before sample collection.
                  </div>
                )}

                {/* Total */}
                <div className="est-total-block">
                  <div className="est-total-row">
                    <span>Tests ({selected.length})</span>
                    <span>₹{total.toFixed(0)}</span>
                  </div>
                  <div className="est-total-row subtotal">
                    <span>Home Collection Charge</span>
                    <span className="est-free">FREE</span>
                  </div>
                  <div className="est-divider"/>
                  <div className="est-total-row grand">
                    <span>Estimated Total</span>
                    <span>₹{total.toFixed(0)}</span>
                  </div>
                  <div className="est-disclaimer">
                    *Indicative estimate. Final amount may vary.
                  </div>
                </div>

                {/* Report time summary */}
                {selected.some(t => t.report_time) && (
                  <div className="est-report-times">
                    <div className="est-rt-title"><Clock size={13}/> Report Times</div>
                    {selected.filter(t => t.report_time).map(t => (
                      <div key={t.id} className="est-rt-row">
                        <span>{t.name}</span>
                        <span>{t.report_time}</span>
                      </div>
                    ))}
                  </div>
                )}

                {/* Actions */}
                <div className="est-actions">
                  <button
                    className="est-action-btn print"
                    onClick={() => printEstimate(selected, prescNote, total)}
                  >
                    <Printer size={15}/> Print / Save PDF
                  </button>
                  <Link
                    to="/book"
                    state={{ preselectedTests: selected.map(t => t.id) }}
                    className="est-action-btn book"
                  >
                    <ShoppingCart size={15}/> Book These Tests
                  </Link>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
